from sympy import symbols, sympify, limit, oo

n = symbols("n")
count = int(input())
for problem in range(count):
    a_text = input()
    p_text = input()
    a = sympify(a_text)
    p = sympify(p_text)
    print(f"Problem {problem + 1}: a_n = {a_text}, b_n = 1/n^({p_text})")
    c = limit(a * n**p, n, oo)
    print(f"  c = lim a_n * n^({p}) = {c}")
    if p > 1:
        b_verdict = "converges"
    else:
        b_verdict = "diverges"
    print(f"  the p-series with p = {p} {b_verdict}")
    if c == oo:
        if b_verdict == "diverges":
            print("  c = oo and the sum of b_n diverges, so the series diverges")
        else:
            print("  c = oo and the sum of b_n converges, so the test decides nothing")
    elif c == 0:
        if b_verdict == "converges":
            print("  c = 0 and the sum of b_n converges, so the series converges")
        else:
            print("  c = 0 and the sum of b_n diverges, so the test decides nothing")
    else:
        print(f"  0 < c < oo, so the series {b_verdict} too")
